\begin{equation}
\label{eq:summarized_y}
y(q) \triangleq \sum_{t=1}^T \langle q, u_t\rangle, \quad \tilde y_\pi(q) \triangleq \sum_{i=1}^m \sum_{t\in\mathcal{C}_i} \langle q, \bar{u}_i\rangle
\end{equation}
The deviation induced by summarization $\operatorname{Err}(\pi ; q) \triangleq\left|y(q)-\tilde{y}_\pi(q)\right|$ admits the bound:

\end{equation}
The deviation induced by summarization $\operatorname{Err}(\pi ; q) \triangleq\left|y(q)-\tilde{y}_\pi(q)\right|$ admits the bound:
\begin{equation}
\label{eq:bound_main}
\big|y(q)-\tilde y_\pi(q)\big|
\;\le\;
\|q\|_2 \cdot \sum_{i=1}^m \sqrt{|\mathcal{C}_i|}
\;\sqrt{\sum_{t\in\mathcal{C}_i}\|u_t-\bar{u}_i\|_2^2}
