\end{equation}
We then use Triangle Inequality~\citep{10.1145/1644893.1644914} over chunks to further get:
\begin{equation}
\label{eq:tri_chunks}
\left\|\sum_{i=1}^m \sum_{t\in\mathcal{C}_i} (u_t-\bar{u}_i)\right\|_2
\le
\sum_{i=1}^m
\left\|\sum_{t\in\mathcal{C}_i} (u_t-\bar{u}_i)\right\|_2
\end{equation}
Similarly, for each block $\mathcal{C}_i$, we also have:
\begin{align}
