\begin{algorithm}[t]
\caption{Capacity-Bounded Memory Modeling}
\label{alg:capacity_bounded_memory_modeling}
\begin{algorithmic}[1]
    \STATE \textbf{Input:} Incoming states $\{S_t\}$, Information Scores $\{\bar I_t\}$, Token Counts $\{n_t\}$, Capacity $K$, Queries $\{q_t\}$
    \STATE \textbf{Output:} attention outputs $\{o_t\}$

\begin{algorithm}[t]
\caption{Capacity-Bounded Memory Modeling}
\label{alg:capacity_bounded_memory_modeling}
\begin{algorithmic}[1]
    \STATE \textbf{Input:} Incoming states $\{S_t\}$, Information Scores $\{\bar I_t\}$, Token Counts $\{n_t\}$, Capacity $K$, Queries $\{q_t\}$
    \STATE \textbf{Output:} attention outputs $\{o_t\}$

\STATE $\mathcal{M} \gets [\ ]$ \COMMENT{state cache}
    \FOR{each $(S_i,\bar I_i,n_i)$ in time order}
        \IF{$|\mathcal{M}| = K$}
            \STATE $(i^\star,i^\star\!+\!1) \gets \arg\min_i \frac{\bar I_i+\bar I_{i+1}}{n_i+n_{i+1}}$
            \STATE $S_{i^\star} \gets S_{i^\star} + S_{i^\star+1}$
            \STATE $n_{i^\star} \gets n_{i^\star} + n_{i^\star+1}$
            \STATE $\bar{I}_{i^\star} \gets \bar{I}_{i^\star} + \bar{I}_{i^\star+1}$
            \STATE remove $S_{i^\star+1}$ from $\mathcal{M}$
        \ENDIF
        \STATE append $(S_i,\bar I_i,n_i)$ to $\mathcal{M}$
    \ENDFOR
    \STATE $o_t = \sum_{i} \phi(q_t)\, S_i$
    \STATE \textbf{return} $\{o_t\}$
\end{algorithmic}
\end{algorithm}

\subsection{Capacity-Bounded Memory Modeling}
\label{subsec:capacity_bounded_memory_modeling}
\textbf{Motivation:} 
While the previous design enables flexible and information-aware memory state construction, maintaining an unbounded number of states is impractical for efficient inference, especially in long-context or high-throughput serving scenarios, as dynamic memory growth leads to irregular memory layouts, variable attention costs, and reduced batching efficiency. To address these challenges, it is essential to explicitly limit the number of memory states while preserving the most informative summaries.

\begin{align}
(i^\star, i^\star\!+\!1) = \arg\min_{i \in \{1,\dots,K-1\}}
\frac{\bar{I}_i + \bar{I}_{i+1}}{n_i + n_{i+1}}
\end{align}
We then merge them using a summarization operator as in~\cref{subsec:information_aware_dynamic_state_merging},
\begin{align}
S_{i^\star} &\leftarrow S_{i^\star} + S_{i^\star+1}, \notag \\
n_{i^\star} &\leftarrow n_{i^\star} + n_{i^\star+1}, \quad
\bar{I}_{i^\star} \leftarrow \bar{I}_{i^\star} + \bar{I}_{i^\star+1}
\end{align}
and shift the remaining states accordingly to keep $m=K-1$ before inserting the incoming state.

Given the capacity-bounded cache $\mathcal{M}$, we compute the output at time step $t$ by attending over the stored memory states. Let $q_t$ denote the query vector of the current token. The final output is then computed as 
\begin{equation}
o_t
= \sum_{i=1}^{m} \lambda_{t,i} \,
q_t^\top
\left(
\sum_{s \in \mathcal{C}_i} v_s k_s^\top
\right)
= \sum_{i=1}^{m} \lambda_{t,i} \,
q_t^\top S_i ,
\label{eq:capacity_bounded_output}
\end{equation}
where $\lambda_{t,i}$ is the weight learned during pre-training with the same shape as the memory capacity. Following~\citep{DBLP:journals/corr/abs-2506-04761}, $\lambda_{t,i}$ is produced by a learned linear layer over the query representation and reused at inference. In this way, \sysname provides a unified way to read from a temporally ordered, capacity-bounded memory, enabling stable inference cost while retaining the ability to emphasize informative states during the inference.

